<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { t, money, n, date } from './lib';
import QueryControls from './QueryControls.vue';
const props=defineProps<{report:any;project:string}>();
const emit=defineEmits<{expand:[]}>();
const dataState=computed(()=>props.report.data_state?.kind||'ready');
const stateText=computed(()=>({outside_retention:t('This entire period is outside the current retention window; historical data is unavailable, not zero.','此区间完全超出当前数据保留范围，历史数据不可查询，不代表零调用。'),window_empty:t('No requests or model calls in this window; the project has data in another retained period.','当前窗口没有请求或模型调用，该项目在其他保留时间内有数据。'),no_retained_data:t('No queryable records in the retention window. Check your integration and retention before sending more data.','当前保留期内没有可查询记录，请先核对接入情况与保留期限。'),no_model_calls:t('Requests were received, but this window has no generation observations. Model cost cannot yet be analyzed.','已收到应用请求，但当前窗口没有模型生成步骤，暂无法分析模型费用。'),partial_pricing:t('Some calls lack usable cost evidence; known cost is a partial subtotal.','部分调用缺少可用费用证据，已知费用并非完整总额。')} as Record<string,string>)[dataState.value]);
const unknownUrl=computed(()=>'/app/traces?'+new URLSearchParams({project:props.project,cost:'unknown',from:props.report.after.start,to:props.report.after.end}));
const page=ref(0),size=ref(5),samplePage=ref(0),sampleSize=ref(5);
watch(()=>props.report,()=>{page.value=0;samplePage.value=0;});
const groups=computed(()=>props.report.contributors.slice(page.value*size.value,(page.value+1)*size.value));
const samples=computed(()=>(props.report.samples||[]).slice(samplePage.value*sampleSize.value,(samplePage.value+1)*sampleSize.value));
const pct=(v:any)=>v==null?'—':`${n(Number(v).toFixed(2))}%`;
const labels:Record<string,[string,string]>={
  RETENTION_INCOMPLETE:['Part of the comparison period is outside your data retention. Changes cannot be reliably compared.','部分对比时间超出数据保留范围，暂不作可靠变化判断。'],
  NO_DATA:['No requests or model calls in this window. Review the period before checking ingestion.','本期窗口没有请求或模型调用，请先核对时间范围，再检查接入情况。'],
  MISSING_PRICES:['Some model calls lack usage or pricing evidence. Review affected calls; known cost is not the complete total.','部分模型调用缺少用量或计价证据，请查看受影响调用；已知费用不是完整总额。'],
  LOW_SAMPLE:['Fewer than 20 model calls in one of the periods. Treat changes as preliminary observations.','至少一个区间不足 20 次模型调用，变化仅供初步观察。'],
  COST_GROWTH:['Known model cost increased by at least 20%. Compare call volume and average call cost below.','模型估算费用增长至少 20%，请结合调用量和每次调用均价查看。'],
  UNIT_COST_GROWTH:['Average model call cost increased by at least 20%. Check model mix, usage and pricing changes.','每次模型调用均价增长至少 20%，建议检查模型组合、用量及价格变化。'],
  INPUT_GROWTH:['Average input length increased by at least 20%. Review context length where appropriate; this alone does not establish a cause.','平均输入 Token 增长至少 20%，可检查上下文长度；这一变化本身不能证明费用增长原因。'],
  ERRORS:['At least 5% of requests failed, with at least 20 requests in this period. Check failed traces.','本期请求不少于 20 条，且失败比例达到 5%，建议检查失败调用。'],
  LATENCY_GROWTH:['P95 latency increased by at least 20%, with at least 20 timed requests in each period.','两个区间均有不少于 20 条耗时记录，P95 延迟增长至少 20%。'],
};
function label(value:any) {
  if(value==null)return t('Unassigned','未归类');
  if(props.report.dimension==='model') {try{return JSON.parse(value).map((v:any)=>v||t('Unknown','未知')).join(' / ');}catch{return value;}}
  return value;
}
const rows=computed(()=>[
  {key:'requests',en:'Requests',zh:'请求数',format:n,delta:null},
  {key:'generations',en:'Model calls',zh:'模型调用数',format:n,delta:props.report.comparison.volume_change_pct},
  {key:'known_cost',en:'Known estimated cost (USD)',zh:'已知模型估算费用（USD）',format:money,delta:props.report.comparison.cost_change_pct},
  {key:'average_model_cost',en:'Average model call cost',zh:'每次模型调用均价',format:money,delta:props.report.comparison.average_cost_change_pct},
  {key:'average_input_tokens',en:'Average input tokens',zh:'平均输入 Token',format:n,delta:props.report.comparison.input_change_pct},
  {key:'p95_ms',en:'P95 latency (ms)',zh:'P95 耗时（毫秒）',format:n,delta:props.report.comparison.p95_change_pct},
  {key:'error_rate',en:'Failed requests',zh:'请求失败比例',format:(v:any)=>v==null?'—':pct(Number(v)*100),delta:null},
]);
</script>
<template>
  <div class="insight-result"><section v-if="stateText" class="notice"><strong>{{stateText}}</strong><p v-if="report.data_state?.retention_cutoff">{{t('Current retention starts','当前保留范围起点')}}: {{date(report.data_state.retention_cutoff)}}</p><button v-if="dataState==='window_empty'" class="btn" @click="emit('expand')">{{t('Expand comparison window','扩大对比窗口')}}</button><RouterLink v-if="dataState==='partial_pricing'" :to="unknownUrl">{{t('View affected requests','查看受影响调用')}}</RouterLink><RouterLink v-if="['no_retained_data','no_model_calls'].includes(dataState)" to="/tutorials">{{t('Review integration examples','查看接入示例')}}</RouterLink><RouterLink v-if="dataState==='outside_retention'" :to="'/app/traces?project='+project">{{t('View recent retained requests','查看近期保留请求')}}</RouterLink></section><template v-if="dataState!=='outside_retention'">
    <section v-if="report.release" class="panel"><h2>{{ t('Release comparison','发布对比') }}：{{ report.release.name }}</h2><p>{{ t('Released at (UTC)','发布时间（UTC）') }}：{{ date(report.release.released_at) }}</p></section>
    <div class="insight-metrics"><article class="panel"><span>{{ t('Known estimated model cost','已知模型估算费用') }}</span><strong>{{ money(report.after.known_cost) }}</strong></article><article class="panel"><span>{{ t('Model calls','模型调用数') }}</span><strong>{{ n(report.after.generations) }}</strong></article><article class="panel"><span>{{ t('Price coverage','价格覆盖率') }}</span><strong>{{ pct(report.after.price_coverage==null?null:Number(report.after.price_coverage)*100) }}</strong></article><article class="panel"><span>{{ t('Requests','请求数') }}</span><strong>{{ n(report.after.requests) }}</strong></article></div>
    <section class="panel"><h2>{{ t('Observations and next steps','发现与建议') }}</h2><ul v-if="report.comparison.findings.length" class="insight-findings"><li v-for="code in report.comparison.findings" :key="code">{{ labels[code] ? t(...labels[code]) : code }} <RouterLink v-if="code==='MISSING_PRICES'" :to="unknownUrl">{{ t('Review unknown-cost calls →','查看未知费用调用 →') }}</RouterLink><RouterLink v-if="code==='ERRORS'" :to="`/app/traces?project=${project}`">{{ t('View traces →','查看调用 →') }}</RouterLink></li></ul><p v-else>{{ t('No configured threshold was crossed in the available data. This is not a guarantee that every request is healthy.','现有数据未触发本页规则阈值，不代表每条请求都没有问题。') }}</p><p class="muted">{{ t('Rules use reported metadata, not an AI-generated root cause. Model prices and traffic mix can affect results. Monitoring subscription charges, revenue and profit are not included.','结论来自已上报数据及规则，不是 AI 推断的根因。模型价格与流量构成会影响结果；不包含监控订阅费、收入或利润。') }}</p></section>
    <section class="panel"><h2>{{ t('Compare periods','区间对比') }}</h2><p>{{ t('Before','前期') }}：{{ date(report.before.start) }} → {{ date(report.before.end) }}</p><p>{{ t('After','本期') }}：{{ date(report.after.start) }} → {{ date(report.after.end) }}</p><p class="muted">{{ t('Start inclusive, end exclusive. Requests are traces; model calls are generation observations, each assigned by its own start time. Data reflects the latest retained revision. Unreported calls cannot be analyzed.','包含起点、不包含终点。请求数统计 Trace，模型调用数统计生成类 Observation，分别按各自开始时间归属区间。数据来自保留期内的最新版本，未上报的调用无法分析。') }}</p><div class="insight-table"><table><thead><tr><th>{{ t('Metric','指标') }}</th><th>{{ t('Before','前期') }}</th><th>{{ t('After','本期') }}</th><th>{{ t('Change','变化') }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.key"><td>{{ t(row.en,row.zh) }}</td><td>{{ row.format(report.before[row.key]) }}</td><td>{{ row.format(report.after[row.key]) }}</td><td>{{ pct(row.delta) }}</td></tr></tbody></table></div><p class="muted">{{ t('A dash means not comparable (including a zero baseline). Averages require complete price or usage coverage. Use the sample counts when interpreting changes.','横线表示无法比较（包括前期为零）。均价或平均用量要求价格或用量完整，解读变化时请同时检查样本量。') }}</p></section>
    <section class="panel"><h2>{{ t('Where the cost is concentrated','费用集中在哪里') }}</h2><p class="muted">{{ t('Top 50 groups by current known cost. Report feature and customer fields on model calls to group them; missing values are unassigned. This does not estimate savings.','按本期已知费用展示前 50 组。需在模型调用中上报功能或客户信息，缺失时归入未归类；不据此估算可节省金额。') }}</p><div class="insight-table"><table><thead><tr><th>{{ t('Group','分组') }}</th><th>{{ t('Model calls','模型调用数') }}</th><th>{{ t('Before cost','前期费用') }}</th><th>{{ t('After cost','本期费用') }}</th><th>{{ t('Unknown cost calls','成本未知调用') }}</th></tr></thead><tbody><tr v-for="(row,i) in groups" :key="i"><td>{{ label(row.label) }}</td><td>{{ n(row.current_calls) }}</td><td>{{ money(row.previous_cost) }}</td><td>{{ money(row.current_cost) }}</td><td>{{ n(row.unknown_costs) }}</td></tr><tr v-if="!groups.length"><td colspan="5" class="empty-cell">{{ t('No model calls in these periods.','这两个区间暂无模型调用。') }}</td></tr></tbody></table></div><QueryControls :page="page" :size="size" :total="report.contributors.length" :loading="false" @change="page=$event" @resize="size=$event;page=0" /></section>
    <section v-if="report.samples" class="panel"><h2>{{ t('Highest-cost reported calls','费用最高的已上报调用') }}</h2><div class="insight-table"><table><thead><tr><th>{{ t('Name','名称') }}</th><th>{{ t('Estimated cost','估算费用') }}</th><th>{{ t('Started at (UTC)','开始时间（UTC）') }}</th></tr></thead><tbody><tr v-for="row in samples" :key="row.object_id"><td><RouterLink v-if="row.trace_id" :to="`/app/trace/${encodeURIComponent(row.trace_id)}?project=${project}`">{{ row.name || row.object_id }}</RouterLink><span v-else>{{ row.name || row.object_id }}</span></td><td>{{ money(row.cost) }}</td><td>{{ date(row.started_at) }}</td></tr><tr v-if="!samples.length"><td colspan="3" class="empty-cell">{{ t('No priced model calls.','暂无已定价模型调用。') }}</td></tr></tbody></table></div><QueryControls :page="samplePage" :size="sampleSize" :total="report.samples.length" :loading="false" @change="samplePage=$event" @resize="sampleSize=$event;samplePage=0" /></section>
  </template></div>
</template>
